import { useEffect, useMemo, useState } from 'react'
import { createClient } from '@supabase/supabase-js'
import { Activity, Blocks, ArrowRight, BarChart3, BookOpen, BrainCircuit, BriefcaseBusiness, CalendarDays, CheckCircle2, ChevronRight, CircleHelp, Code2, Coins, ExternalLink, GraduationCap, Headphones, LayoutDashboard, LogOut, Menu, MessageCircle, Moon, Plus, Rocket, Search, Send, ShieldAlert, ShieldCheck, Sparkles, Sun, Target, Ticket, Trash2, TrendingUp, Users, Video, Wallet, X } from 'lucide-react'

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL
const supabaseKey = import.meta.env.VITE_SUPABASE_ANON_KEY
const supabase = supabaseUrl && supabaseKey ? createClient(supabaseUrl, supabaseKey) : null

const areas = [
  {name:'Inteligência artificial',icon:BrainCircuit,desc:'Use IA para estudar, produzir e automatizar.'},
  {name:'Programação e tecnologia',icon:Code2,desc:'Crie sites, aplicativos e soluções digitais.'},
  {name:'Marketing e vendas',icon:TrendingUp,desc:'Aprenda aquisição, conteúdo e conversão.'},
  {name:'Empreendedorismo',icon:BriefcaseBusiness,desc:'Valide ideias, encontre clientes e construa negócios.'},
  {name:'Finanças e investimentos',icon:Coins,desc:'Entenda dinheiro, risco, mercado e planejamento.'},
  {name:'Carreira e habilidades',icon:GraduationCap,desc:'Desenvolva competências e monte seu portfólio.'}
]
const goals = ['Conseguir meu primeiro trabalho ou cliente','Criar uma fonte de renda','Abrir ou melhorar um negócio','Aprender tecnologia e IA','Organizar minhas finanças','Explorar possibilidades e descobrir meu caminho']
const timeOptions = ['Até 30 minutos','30 a 60 minutos','1 a 2 horas','Mais de 2 horas']
const SUPPORT_WHATSAPP = '5563992342186'

function App(){
  const [session,setSession]=useState(null),[profile,setProfile]=useState(null),[isAdmin,setIsAdmin]=useState(false)
  const [courses,setCourses]=useState([]),[lessons,setLessons]=useState([]),[tools,setTools]=useState([])
  const [page,setPage]=useState('home'),[selectedCourse,setSelectedCourse]=useState(null),[selectedLesson,setSelectedLesson]=useState(null)
  const [loading,setLoading]=useState(true),[authMode,setAuthMode]=useState('login'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[fullName,setFullName]=useState(''),[notice,setNotice]=useState('')
  const [search,setSearch]=useState(''),[mobileMenu,setMobileMenu]=useState(false),[chatOpen,setChatOpen]=useState(false),[chatInput,setChatInput]=useState(''),[chatMessages,setChatMessages]=useState([]),[chatBusy,setChatBusy]=useState(false)
  const [answers,setAnswers]=useState({goal:'',areas:[],time:'',experience:'',known_platforms:'',current_activity:'',six_month_goal:'',personal_vision:'',guardian_email:'',age_group:'unverified'})
  const [saving,setSaving]=useState(false),[activationCode,setActivationCode]=useState(''),[signupAgeGroup,setSignupAgeGroup]=useState('adult'),[guardianEmail,setGuardianEmail]=useState('')
  const [darkMode,setDarkMode]=useState(false)
  useEffect(()=>{setDarkMode(window.localStorage.getItem('azelf-theme')==='dark')},[])
  useEffect(()=>{window.localStorage.setItem('azelf-theme',darkMode?'dark':'light')},[darkMode])
  useEffect(()=>{ if(!supabase){setLoading(false);return} supabase.auth.getSession().then(({data})=>setSession(data.session)); const {data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s)); return ()=>subscription.unsubscribe() },[])
  useEffect(()=>{ if(session?.user) loadWorkspace(); else {setProfile(null);setIsAdmin(false);setCourses([]);setLessons([]);setTools([]);setLoading(false)} },[session])
  async function loadWorkspace(){
    setLoading(true); const uid=session.user.id
    const [p,r,c,l,t]=await Promise.all([
      supabase.from('profiles').select('*').eq('id',uid).maybeSingle(),
      supabase.from('user_roles').select('role').eq('user_id',uid).maybeSingle(),
      supabase.from('courses').select('*').eq('is_published',true).order('sort_order'),
      supabase.from('lessons').select('*').eq('is_published',true).order('sort_order'),
      supabase.from('tools').select('*').eq('is_published',true).order('sort_order')
    ])
    setProfile(p.data||null); setIsAdmin(r.data?.role==='admin'); setCourses(c.data||[]); setLessons(l.data||[]); setTools(t.data||[]); setLoading(false)
  }
  async function trackActivity(event_type,entity_type=null,entity_id=null,metadata={}){if(!session?.user?.id)return;try{await supabase.from('learning_activity').insert({user_id:session.user.id,event_type,entity_type,entity_id,metadata})}catch(error){console.warn('activity log unavailable',error)}}
  const visibleCourses=useMemo(()=>courses.filter(c=>(profile?.age_group==='adult'||!c.adult_only)&&(!search||[c.title,c.description,c.category].join(' ').toLowerCase().includes(search.toLowerCase()))),[courses,profile,search])
  async function authenticate(e){
    e.preventDefault();setNotice('');setSaving(true);
    try {
      if(authMode==='signup'){
        if(!activationCode.trim()) throw new Error('Informe seu código de ativação.');
        if(password.length<10) throw new Error('Use uma senha com pelo menos 10 caracteres.');
        if(signupAgeGroup==='minor'&&!guardianEmail.trim()) throw new Error('Informe o e-mail do responsável legal.');
        const {data,error}=await supabase.functions.invoke('activate-account',{body:{
          code:activationCode,email,password,full_name:fullName,age_group:signupAgeGroup,
          guardian_email:guardianEmail
        }});
        if(error) throw error;
        if(data?.error) throw new Error(data.error);
        if(signupAgeGroup==='minor'){
          setNotice('Conta criada. O acesso ficará pendente até a equipe confirmar o responsável legal. O responsável será contatado conforme o procedimento de validação.');
          setAuthMode('login'); return;
        }
        const login=await supabase.auth.signInWithPassword({email,password});
        if(login.error) throw login.error;
        setNotice('Conta criada e ativada.');
      } else {
        const {error}=await supabase.auth.signInWithPassword({email,password});
        if(error) throw error;
        setNotice('Login realizado.');
      }
    } catch(err) { setNotice(err?.message||'Não foi possível concluir a operação.'); }
    finally { setSaving(false); }
  }
  async function signOut(){await supabase.auth.signOut();setPage('home')}
  async function saveOnboarding(e){e.preventDefault();setSaving(true);const {error}=await supabase.from('profiles').upsert({id:session.user.id,full_name:fullName||session.user.user_metadata?.full_name||'',age_group:answers.age_group,guardian_email:answers.age_group==='minor'?answers.guardian_email:null,onboarding_completed:answers.age_group!=='minor',access_status:answers.age_group==='minor'?'pending':undefined,guardian_consent_status:answers.age_group==='minor'?'pending':undefined,onboarding_answers:answers},{onConflict:'id'});setSaving(false);if(error)setNotice(error.message);else{await trackActivity('onboarding_completed','profile',session.user.id,{goal:answers.goal,interests:answers.areas});if(answers.age_group==='minor'){setNotice('Diagnóstico recebido. O acesso ficará pendente até a validação do responsável legal.');await loadWorkspace()}else{setNotice('Diagnóstico salvo. Seu plano inicial está pronto.');await loadWorkspace();setPage('dashboard')}}}
  async function toggleProgress(lesson){const {error}=await supabase.from('lesson_progress').upsert({user_id:session.user.id,lesson_id:lesson.id,completed:true,completed_at:new Date().toISOString()},{onConflict:'user_id,lesson_id'});if(error)setNotice('Não foi possível salvar o progresso: '+error.message);else{await trackActivity('lesson_completed','lesson',lesson.id,{title:lesson.title});setNotice('Aula marcada como concluída.')}}
  async function askTutor(e){e.preventDefault();if(!chatInput.trim()||!supabase)return;const text=chatInput.trim();setChatInput('');setChatMessages(m=>[...m,{role:'user',content:text}]);setChatBusy(true);await trackActivity('tutor_question',selectedLesson?'lesson':selectedCourse?'course':'general',selectedLesson?.id||selectedCourse?.id||null,{question:text.slice(0,700),course:selectedCourse?.title||null,lesson:selectedLesson?.title||null});try{const {data,error}=await supabase.functions.invoke('ai-tutor',{body:{message:text,context:{page,course_title:selectedCourse?.title||'',lesson_title:selectedLesson?.title||'',lesson_summary:selectedLesson?.summary||'',lesson_content:selectedLesson?.content_md||'',learner_goal:profile?.onboarding_answers?.goal||'',learning_interests:(profile?.onboarding_answers?.areas||[]).join(', '),known_platforms:profile?.onboarding_answers?.known_platforms||'',current_activity:profile?.onboarding_answers?.current_activity||'',experience_level:profile?.onboarding_answers?.experience||'',six_month_goal:profile?.onboarding_answers?.six_month_goal||'',personal_vision:profile?.onboarding_answers?.personal_vision||''}}});if(error)throw error;const answer=data?.answer||data?.response||data?.message||'Recebi sua pergunta, mas não encontrei o texto da resposta.';setChatMessages(m=>[...m,{role:'assistant',content:answer}])}catch(err){setChatMessages(m=>[...m,{role:'assistant',content:'Não consegui acessar o tutor agora. Verifique a função ai-tutor e tente novamente.'}])}finally{setChatBusy(false)}}
  const lessonsFor=course=>lessons.filter(l=>l.course_id===course.id&&(profile?.age_group==='adult'||!l.adult_only))
  if(!supabase)return <SetupScreen/>
  return <div className={darkMode?'app-shell dark-mode':'app-shell'}>
    <header className="topbar"><button className="brand" onClick={()=>setPage(session?'dashboard':'home')}><span className="brand-mark">A</span><span>AZELF<small>APRENDER · CRIAR · EVOLUIR</small></span></button>
      <button className="mobile-toggle" onClick={()=>setMobileMenu(!mobileMenu)} aria-label="Menu">{mobileMenu?<X/>:<Menu/>}</button>
      <nav className={mobileMenu?'nav open':'nav'}><button onClick={()=>{setPage(session?'dashboard':'home');setMobileMenu(false)}}>Início</button><button onClick={()=>{setPage('courses');setMobileMenu(false)}}>Aprender</button><button onClick={()=>{setPage('lab');setMobileMenu(false)}}>Laboratórios</button><button onClick={()=>{setPage('tools');setMobileMenu(false)}}>Ferramentas</button>{session&&<button onClick={()=>{setPage('support');setMobileMenu(false)}}>Ajuda</button>}<button onClick={()=>{setChatOpen(true);setMobileMenu(false)}}>Tutor IA</button>{isAdmin&&<button onClick={()=>{setPage('admin');setMobileMenu(false)}}>Admin</button>}</nav>
      <div className="top-actions"><button className="icon-button theme-toggle" onClick={()=>setDarkMode(v=>!v)} title={darkMode?'Ativar tema claro':'Ativar tema escuro'}>{darkMode?<Sun size={18}/>:<Moon size={18}/>}</button>{session?<><span className="user-pill">{isAdmin?'ADMINISTRADOR':profile?.full_name||session.user.email}</span><button className="icon-button" onClick={signOut} title="Sair"><LogOut size={18}/></button></>:<button className="button button-small" onClick={()=>setPage('auth')}>Entrar <ArrowRight size={16}/></button>}</div>
    </header>
    <main>
      {loading?<div className="loading">Carregando sua área de aprendizagem…</div>:!session&&page!=='auth'?<Landing onStart={()=>setPage('auth')}/>:!session&&page==='auth'?<section className="auth-wrap"><div className="auth-card"><span className="eyebrow">SUA PRÓXIMA FASE COMEÇA AQUI</span><h1>{authMode==='login'?'Entre na AZELF':'Crie sua conta'}</h1><p>Aprenda habilidades úteis e transforme conhecimento em projetos reais.</p><form onSubmit={authenticate}>{authMode==='signup'&&<><label>Nome completo<input value={fullName} onChange={e=>setFullName(e.target.value)} required placeholder="Como podemos chamar você?"/></label><label>Código de convite<input value={activationCode} onChange={e=>setActivationCode(e.target.value.toUpperCase())} required placeholder="Código gerado pelo administrador"/></label><label>Faixa etária<select value={signupAgeGroup} onChange={e=>setSignupAgeGroup(e.target.value)}><option value="adult">18 anos ou mais</option><option value="minor">Menos de 18 anos</option></select></label>{signupAgeGroup==='minor'&&<label>E-mail do responsável legal<input type="email" value={guardianEmail} onChange={e=>setGuardianEmail(e.target.value)} required placeholder="responsavel@email.com"/></label>}</>}<label>E-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required placeholder="voce@email.com"/></label><label>Senha<input type="password" value={password} onChange={e=>setPassword(e.target.value)} minLength="10" required placeholder="Mínimo de 10 caracteres"/></label><button className="button button-full" disabled={saving}>{saving?'Aguarde…':authMode==='login'?'Entrar':'Criar conta com convite'}</button></form>{notice&&<p className="notice">{notice}</p>}<button className="text-button" onClick={()=>{setAuthMode(authMode==='login'?'signup':'login');setNotice('')}}>{authMode==='login'?'Tem um código de convite? Criar conta':'Já tem conta? Entrar'}</button></div></section>:profile?.age_group==='minor'&&profile?.access_status!=='active'?<section className="workspace"><div className="panel"><ShieldCheck/><h1>Acesso aguardando responsável</h1><p>Seu cadastro foi recebido. A equipe AZELF precisa validar o consentimento do responsável antes de liberar o conteúdo.</p></div></section>:!profile?.onboarding_completed&&!isAdmin?<Onboarding answers={answers} setAnswers={setAnswers} fullName={fullName} setFullName={setFullName} save={saveOnboarding} saving={saving} notice={notice}/>:page==='admin'&&isAdmin?<Admin courses={courses} lessons={lessons} tools={tools} profile={profile}/>:page==='courses'?<Courses courses={visibleCourses} lessonsFor={lessonsFor} openCourse={c=>{trackActivity('course_opened','course',c.id,{title:c.title});setSelectedCourse(c);setPage('course')}} search={search} setSearch={setSearch}/>:page==='course'&&selectedCourse?<Course course={selectedCourse} lessons={lessonsFor(selectedCourse)} openLesson={l=>{trackActivity('lesson_opened','lesson',l.id,{title:l.title,course:selectedCourse.title});setSelectedLesson(l);setPage('lesson')}} back={()=>setPage('courses')}/>:page==='lesson'&&selectedLesson?<Lesson lesson={selectedLesson} course={selectedCourse} back={()=>setPage('course')} complete={()=>toggleProgress(selectedLesson)} ask={()=>setChatOpen(true)}/>:page==='tools'?<Tools tools={tools} profile={profile}/>:page==='lab'?<LearningLab openCrypto={()=>setPage('crypto-lab')}/>:page==='crypto-lab'?<CryptoLab back={()=>setPage('lab')}/>:page==='support'?<Support session={session} profile={profile} onTicketCreated={()=>trackActivity('support_requested','support',null,{source:'help_center'})}/>:page==='dashboard'?<Dashboard profile={profile} courses={visibleCourses} lessons={lessons} openCourses={()=>setPage('courses')} openChat={()=>setChatOpen(true)} openOnboarding={()=>setPage('onboarding')} openLab={()=>setPage('lab')} openSupport={()=>setPage('support')}/>:page==='onboarding'?<Onboarding answers={answers} setAnswers={setAnswers} fullName={fullName} setFullName={setFullName} save={saveOnboarding} saving={saving} notice={notice}/>:<Dashboard profile={profile} courses={visibleCourses} lessons={lessons} openCourses={()=>setPage('courses')} openChat={()=>setChatOpen(true)} openOnboarding={()=>setPage('onboarding')} openLab={()=>setPage('lab')} openSupport={()=>setPage('support')}/>}
    </main>
    <footer><span>AZELF © {new Date().getFullYear()}</span><span>Conhecimento aplicado. Progresso real.</span><span>Conteúdo educacional — resultados dependem de prática e contexto.</span></footer>
    {session&&<button className="chat-fab" onClick={()=>setChatOpen(true)} aria-label="Abrir tutor IA"><MessageCircle/><span>Tutor IA</span></button>}
    {chatOpen&&<div className="chat-panel"><div className="chat-head"><div><strong><Sparkles size={17}/> Tutor AZELF</strong><small>Assistente de aprendizagem</small></div><button className="icon-button" onClick={()=>setChatOpen(false)}><X/></button></div><div className="chat-body">{chatMessages.length===0&&<div className="chat-welcome"><BrainCircuit size={28}/><strong>O que você quer aprender ou resolver?</strong><p>Posso explicar conceitos, ajudar com exercícios e orientar seu próximo passo.</p></div>}{chatMessages.map((m,i)=><div key={i} className={'chat-msg '+m.role}>{m.content}</div>)}{chatBusy&&<div className="chat-msg assistant">Pensando…</div>}</div><form className="chat-form" onSubmit={askTutor}><input value={chatInput} onChange={e=>setChatInput(e.target.value)} placeholder="Digite sua pergunta…" /><button className="button" disabled={chatBusy}><ArrowRight/></button></form></div>}
  </div>
}

function SetupScreen(){return <div className="setup"><div className="brand-mark">A</div><h1>AZELF</h1><h2>Configuração de publicação necessária</h2><p>O código está pronto para receber as variáveis públicas do Supabase no Cloudflare Pages:</p><code>VITE_SUPABASE_URL</code><code>VITE_SUPABASE_ANON_KEY</code><p>As chaves secretas da OpenAI permanecem exclusivamente nos Supabase Edge Function Secrets.</p></div>}
function Landing({onStart}){return <><section className="hero"><div className="hero-copy"><span className="eyebrow"><Sparkles size={15}/> CONHECIMENTO QUE VIRA CAPACIDADE</span><h1>Seu próximo passo<br/><em>começa com o que você aprende.</em></h1><p>Aprenda, pratique em laboratórios interativos e transforme habilidades em projetos reais — no seu ritmo, com orientação de IA.</p><div className="hero-buttons"><button className="button" onClick={onStart}>Entrar na AZELF <ArrowRight size={18}/></button><span>Uma jornada que começa com seu objetivo, não com um curso aleatório.</span></div><div className="hero-proof"><div><strong>Aprender</strong><small>Conhecimento aplicado</small></div><div><strong>Experimentar</strong><small>Simulações seguras</small></div><div><strong>Construir</strong><small>Portfólio e renda</small></div></div></div><div className="hero-art hero-3d-stage"><div className="orbit orbit-one"></div><div className="orbit orbit-two"></div><div className="orbit orbit-three"></div><div className="hero-3d-orb"><div className="orb-core"><span>A</span><small>AZELF</small></div><i className="orb-ring ring-a"></i><i className="orb-ring ring-b"></i><i className="orb-glow"></i></div><div className="float-card card-top"><BrainCircuit/> Inteligência artificial</div><div className="float-card card-right"><Blocks/> Blockchain na prática</div><div className="float-card card-bottom"><Target/> Seu plano de evolução</div></div></section><section className="section"><div className="section-heading"><span className="eyebrow">APRENDA E APLIQUE</span><h2>Não fique só assistindo. Construa.</h2><p>Trilhas, desafios, simuladores, tutoria de IA e projetos guiados em uma jornada adaptada à sua realidade.</p></div><div className="area-grid">{areas.map(a=><div className="area-card" key={a.name}><a.icon/><h3>{a.name}</h3><p>{a.desc}</p><ChevronRight/></div>)}</div><div className="landing-lab-promo"><div><span className="eyebrow">LABORATÓRIO INTERATIVO</span><h2>Explore sem arriscar dinheiro real.</h2><p>Entenda blockchain, tokens, carteiras, gráfico, custos e margem usando simulações que deixam cada etapa visível.</p></div><div className="lab-promo-mark"><Blocks size={40}/><span>SIMULAÇÃO</span></div></div></section><section className="quote-band"><span>“O futuro não muda com intenção. Muda com conhecimento aplicado, consistência e ação.”</span><small>AZELF · APRENDER. CRIAR. EVOLUIR.</small></section></>}
function Dashboard({profile,courses,lessons,openCourses,openChat,openOnboarding,openLab,openSupport}){return <section className="workspace"><div className="welcome-row"><div><span className="eyebrow">SUA CENTRAL DE EVOLUÇÃO</span><h1>Olá, {profile?.full_name?.split(' ')[0]||'estudante'}.</h1><p>Seu próximo passo é transformar uma habilidade em algo demonstrável.</p></div><div className="welcome-mark"><Sparkles/></div></div><div className="stats-grid"><Stat label="Trilhas disponíveis" value={courses.length} icon={BookOpen}/><Stat label="Aulas práticas" value={lessons.length} icon={GraduationCap}/><Stat label="Áreas de desenvolvimento" value="6" icon={Target}/></div><div className="dashboard-grid"><div className="panel panel-main"><div className="panel-title"><div><span className="eyebrow">CONTINUE EVOLUINDO</span><h2>Escolha uma trilha</h2></div><button className="text-button" onClick={openCourses}>Ver todas <ArrowRight size={15}/></button></div>{courses.slice(0,5).map(c=><button className="course-row" key={c.id} onClick={openCourses}><span className="course-icon"><BookOpen/></span><span><strong>{c.title}</strong><small>{c.category} · {c.description||'Aprenda e pratique'}</small></span><ChevronRight/></button>)}</div><div className="panel"><span className="eyebrow">SUA CAIXA DE FERRAMENTAS</span><h2>Aprender fazendo.</h2><p>Experimente um laboratório de blockchain, simulação de mercado e cálculo de margem sem colocar dinheiro real em risco.</p><button className="button button-full" onClick={openLab}><Blocks size={17}/> Abrir laboratórios</button><button className="outline-button button-full" onClick={openChat}><MessageCircle size={17}/> Perguntar ao tutor</button><button className="outline-button button-full" onClick={openSupport}><Headphones size={17}/> Pedir ajuda</button><button className="text-button" onClick={openOnboarding}>Atualizar meu diagnóstico</button></div></div></section>}
function Stat({label,value,icon:Icon}){return <div className="stat-card"><Icon/><strong>{value}</strong><small>{label}</small></div>}
function Courses({courses,lessonsFor,openCourse,search,setSearch}){return <section className="workspace"><div className="section-heading left"><span className="eyebrow">BIBLIOTECA AZELF</span><h1>Trilhas de aprendizagem</h1><p>Escolha uma habilidade, estude e aplique em um projeto.</p></div><div className="search-box"><Search/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar por curso, tema ou habilidade…"/></div><div className="course-grid">{courses.map(c=><button className="course-card" key={c.id} onClick={()=>openCourse(c)}><div className="course-card-top"><span className="course-icon"><BookOpen/></span><span>{c.category}</span></div><h3>{c.title}</h3><p>{c.description}</p><div className="course-card-bottom"><span>{lessonsFor(c).length} aulas</span><span>Explorar <ArrowRight size={15}/></span></div></button>)}</div>{courses.length===0&&<p className="empty">Nenhuma trilha encontrada para essa busca.</p>}</section>}
function Course({course,lessons,openLesson,back}){return <section className="workspace"><button className="back-button" onClick={back}>← Todas as trilhas</button><div className="section-heading left"><span className="eyebrow">{course.category}</span><h1>{course.title}</h1><p>{course.description}</p></div><div className="lesson-list">{lessons.map((l,i)=><button className="lesson-row" key={l.id} onClick={()=>openLesson(l)}><span className="lesson-number">{String(i+1).padStart(2,'0')}</span><span><strong>{l.title}</strong><small>{l.summary||'Aula prática'} · {l.estimated_minutes||10} min</small></span><ChevronRight/></button>)}</div></section>}
function Lesson({lesson,course,back,complete,ask}){return <section className="workspace lesson-page"><button className="back-button" onClick={back}>← {course?.title||'Voltar'}</button><span className="eyebrow">AULA · {lesson.estimated_minutes||10} MIN</span><h1>{lesson.title}</h1><p className="lesson-summary">{lesson.summary}</p><article className="lesson-content">{(lesson.content_md||'O conteúdo desta aula está sendo preparado. Use o tutor para tirar dúvidas sobre este tema.').split('\n').map((line,i)=>line.startsWith('#')?<h2 key={i}>{line.replace(/^#+\s*/,'')}</h2>:<p key={i}>{line}</p>)}</article><div className="lesson-actions"><button className="button" onClick={complete}><CheckCircle2/> Marcar como concluída</button><button className="outline-button" onClick={ask}><MessageCircle/> Tirar dúvidas com IA</button></div></section>}
function Tools({tools,profile}){const list=tools.filter(t=>profile?.age_group==='adult'||!t.adult_only);return <section className="workspace"><div className="section-heading left"><span className="eyebrow">CAIXA DE FERRAMENTAS</span><h1>Ferramentas para fazer acontecer.</h1><p>Conheça recursos digitais e aprenda a usá-los com propósito.</p></div><div className="tool-grid">{list.map(t=><article className="tool-card" key={t.id}><span className="tool-icon"><Code2/></span><h3>{t.name}</h3><small>{t.category} · {t.access_label}</small><p>{t.description}</p>{t.tutorial&&<details><summary>Como usar</summary><p>{t.tutorial}</p></details>}<a href={t.official_url} target="_blank" rel="noreferrer">Site oficial <ArrowRight size={14}/></a></article>)}</div></section>}
function Onboarding({answers,setAnswers,fullName,setFullName,save,saving,notice}){function set(k,v){setAnswers(a=>({...a,[k]:v}))}function area(name){set('areas',answers.areas.includes(name)?answers.areas.filter(x=>x!==name):[...answers.areas,name])}return <section className="onboarding"><div className="onboarding-head"><span className="eyebrow">DIAGNÓSTICO INICIAL</span><h1>Vamos descobrir seu próximo passo.</h1><p>Suas respostas ajudam a organizar uma jornada de aprendizagem mais relevante.</p></div><form onSubmit={save} className="onboarding-form"><label>Como podemos chamar você?<input value={fullName} onChange={e=>setFullName(e.target.value)} placeholder="Seu nome"/></label><fieldset><legend>1. Qual é seu principal objetivo agora?</legend><div className="choice-grid">{goals.map(g=><button type="button" className={answers.goal===g?'choice selected':'choice'} onClick={()=>set('goal',g)} key={g}>{g}</button>)}</div></fieldset><fieldset><legend>2. Quais áreas você quer explorar?</legend><div className="choice-grid">{areas.map(a=><button type="button" className={answers.areas.includes(a.name)?'choice selected':'choice'} onClick={()=>area(a.name)} key={a.name}>{a.name}</button>)}</div></fieldset><fieldset><legend>3. Quanto tempo você pode dedicar por dia?</legend><div className="choice-grid">{timeOptions.map(t=><button type="button" className={answers.time===t?'choice selected':'choice'} onClick={()=>set('time',t)} key={t}>{t}</button>)}</div></fieldset><fieldset><legend>4. Como você descreve seu momento atual?</legend><div className="choice-grid">{['Estou começando do zero','Já estudo por conta própria','Já trabalho ou vendo algo','Tenho um negócio ou projeto'].map(t=><button type="button" className={answers.experience===t?'choice selected':'choice'} onClick={()=>set('experience',t)} key={t}>{t}</button>)}</div></fieldset><fieldset><legend>5. Quais plataformas ou ferramentas você já conhece?</legend><label><input value={answers.known_platforms} onChange={e=>set('known_platforms',e.target.value)} placeholder="Ex.: Canva, Instagram, Excel, ChatGPT, Shopify…"/></label><small>Liste apenas nomes de plataformas; não informe senhas ou dados privados.</small></fieldset><fieldset><legend>6. Com o que você trabalha, estuda ou costuma fazer?</legend><label><input value={answers.current_activity} onChange={e=>set('current_activity',e.target.value)} placeholder="Ex.: estudante, comércio, edição de vídeo, atendimento…"/></label></fieldset><fieldset><legend>7. O que gostaria de conquistar nos próximos seis meses?</legend><label><input value={answers.six_month_goal} onChange={e=>set('six_month_goal',e.target.value)} placeholder="Descreva uma meta concreta."/></label></fieldset><fieldset><legend>8. Qual é sua visão de futuro ou maior objetivo?</legend><label><input value={answers.personal_vision} onChange={e=>set('personal_vision',e.target.value)} placeholder="O que você gostaria de construir a longo prazo?"/></label></fieldset><fieldset><legend>9. Qual é sua faixa etária?</legend><div className="choice-grid"><button type="button" className={answers.age_group==='minor'?'choice selected':'choice'} onClick={()=>set('age_group','minor')}>Menos de 18 anos</button><button type="button" className={answers.age_group==='adult'?'choice selected':'choice'} onClick={()=>set('age_group','adult')}>18 anos ou mais</button></div><small>Essa informação serve para adequar conteúdos e proteger sua experiência. Recursos restritos permanecem sujeitos a verificações adicionais.</small>{answers.age_group==='minor'&&<label>E-mail do responsável legal<input type="email" value={answers.guardian_email} onChange={e=>set('guardian_email',e.target.value)} required placeholder="responsavel@email.com"/></label>}</fieldset><fieldset><legend>10. Qual faixa representa sua idade?</legend><div className="choice-grid">{['13–15 anos','16–17 anos','18–24 anos','25–34 anos','35–44 anos','45 anos ou mais'].map(v=><button type="button" className={answers.age_bracket===v?'choice selected':'choice'} onClick={()=>set('age_bracket',v)} key={v}>{v}</button>)}</div></fieldset><fieldset><legend>11. Quais habilidades você já sabe fazer?</legend><label><textarea rows="3" value={answers.skills_available||''} onChange={e=>set('skills_available',e.target.value)} placeholder="Ex.: edição, atendimento, escrita, design, vendas, organização…"/></label></fieldset><fieldset><legend>12. Você já tem público ou clientes?</legend><div className="choice-grid">{['Ainda não','Amigos e contatos próximos','Até 500 seguidores/clientes','Mais de 500','Já tenho clientes recorrentes'].map(v=><button type="button" className={answers.audience===v?'choice selected':'choice'} onClick={()=>set('audience',v)} key={v}>{v}</button>)}</div></fieldset><fieldset><legend>13. Como você aprende melhor?</legend><div className="choice-grid">{['Vídeos curtos e demonstrações','Passo a passo com prática','Projetos e desafios','Leitura com exemplos','Mistura de tudo'].map(v=><button type="button" className={answers.learning_style===v?'choice selected':'choice'} onClick={()=>set('learning_style',v)} key={v}>{v}</button>)}</div></fieldset><fieldset><legend>14. O que mais está dificultando seu avanço?</legend><div className="choice-grid">{['Não sei por onde começar','Falta de tempo','Falta de dinheiro para ferramentas','Falta de confiança ou orientação','Não consigo encontrar clientes','Já comecei, mas não termino'].map(v=><button type="button" className={answers.biggest_blocker===v?'choice selected':'choice'} onClick={()=>set('biggest_blocker',v)} key={v}>{v}</button>)}</div></fieldset><fieldset><legend>15. O que você gostaria de ensinar a outra pessoa?</legend><label><textarea rows="3" value={answers.teachable_skills||''} onChange={e=>set('teachable_skills',e.target.value)} placeholder="Mesmo que pareça simples, conte o que você sabe fazer."/></label></fieldset><button className="button" disabled={saving||!answers.goal||!answers.areas.length||!answers.time||!answers.experience||!answers.age_group||(answers.age_group==='minor'&&!answers.guardian_email.trim())}>{saving?'Salvando…':'Salvar diagnóstico e montar minha jornada'} <ArrowRight/></button>{notice&&<p className="notice">{notice}</p>}</form></section>}
function Admin({courses,lessons,tools,profile}){
  const [tab,setTab]=useState('overview'),[stats,setStats]=useState({users:0,active:0,pending:0,lessonsDone:0,questions:0,openTickets:0,activity7d:0}),[trend,setTrend]=useState([])
  const [users,setUsers]=useState([]),[codes,setCodes]=useState([]),[events,setEvents]=useState([]),[tickets,setTickets]=useState([]),[posts,setPosts]=useState([])
  const [email,setEmail]=useState(''),[label,setLabel]=useState(''),[days,setDays]=useState(30),[newCode,setNewCode]=useState('')
  const [selectedTicket,setSelectedTicket]=useState(null),[reply,setReply]=useState(''),[ticketStatus,setTicketStatus]=useState('in_progress')
  const [platform,setPlatform]=useState('instagram'),[postTitle,setPostTitle]=useState(''),[caption,setCaption]=useState(''),[mediaUrl,setMediaUrl]=useState(''),[postDate,setPostDate]=useState(''),[postStatus,setPostStatus]=useState('draft'),[publishedUrl,setPublishedUrl]=useState('')
  const [courseId,setCourseId]=useState(courses[0]?.id||''),[courseTitle,setCourseTitle]=useState(''),[courseDescription,setCourseDescription]=useState(''),[courseCategory,setCourseCategory]=useState('Negócios')
  const [lessonTitle,setLessonTitle]=useState(''),[lessonSummary,setLessonSummary]=useState(''),[lessonContent,setLessonContent]=useState(''),[lessonMinutes,setLessonMinutes]=useState(25),[editingLesson,setEditingLesson]=useState(null)
  const [busy,setBusy]=useState(false),[message,setMessage]=useState(''),[filter,setFilter]=useState('')
  async function call(name,body){const {data,error}=await supabase.functions.invoke(name,{body});if(error)throw error;if(data?.error)throw new Error(data.error);return data}
  async function loadOverview(){try{const d=await call('admin-manage',{action:'overview'});setStats(s=>({...s,...d.stats}))}catch(e){setMessage(e.message)}}
  async function loadDashboard(){try{const d=await call('admin-manage',{action:'admin-dashboard'});setStats(s=>({...s,...d.stats}));setTrend(d.trend||[])}catch(e){setMessage(e.message)}}
  async function loadUsers(){try{const d=await call('admin-manage',{action:'users'});setUsers(d.users||[])}catch(e){setMessage(e.message)}}
  async function loadCodes(){try{const d=await call('admin-codes',{action:'list'});setCodes(d.codes||[])}catch(e){setMessage(e.message)}}
  async function loadEvents(){try{const d=await call('admin-manage',{action:'activity'});setEvents(d.events||[])}catch(e){setMessage(e.message)}}
  async function loadTickets(){try{const d=await call('admin-manage',{action:'tickets'});setTickets(d.tickets||[])}catch(e){setMessage(e.message)}}
  async function loadPosts(){try{const d=await call('admin-manage',{action:'social-posts'});setPosts(d.posts||[])}catch(e){setMessage(e.message)}}
  useEffect(()=>{loadOverview();loadDashboard()},[])
  async function switchTab(next){setTab(next);setMessage('');if(next==='users')await loadUsers();if(next==='codes')await loadCodes();if(next==='activity')await loadEvents();if(next==='tickets')await loadTickets();if(next==='social')await loadPosts();if(next==='overview'){await loadOverview();await loadDashboard()}}
  async function generate(e){e.preventDefault();setBusy(true);setMessage('');setNewCode('');try{const d=await call('admin-codes',{action:'generate',customer_email:email,customer_label:label,validity_days:Number(days)});setNewCode(d.code||'');setMessage(d.warning||'Código gerado. Copie agora; ele não será exibido novamente.');setEmail('');setLabel('');await loadCodes();await loadOverview()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function revoke(id){if(!confirm('Revogar este código não utilizado?'))return;try{await call('admin-codes',{action:'revoke',id});setMessage('Código revogado.');await loadCodes();await loadOverview()}catch(e){setMessage(e.message)}}
  async function setUserStatus(user,status){const minorApproval=status==='active'&&user.age_group==='minor'&&user.guardian_consent_status!=='approved';const prompt=minorApproval?'Confirme que o consentimento do responsável legal foi realmente recebido e verificado.':' '+(status==='active'?'Ativar':'Suspender')+' o acesso de '+(user.email||user.full_name)+'?';if(!confirm(prompt))return;try{if(minorApproval)await call('admin-manage',{action:'approve-guardian',user_id:user.id});else await call('admin-manage',{action:'set-user-status',user_id:user.id,status});setMessage(minorApproval?'Verificação manual do responsável registrada.':'Acesso atualizado.');await loadUsers();await loadOverview()}catch(e){setMessage(e.message)}}
  async function answerTicket(e){e.preventDefault();if(!selectedTicket)return;setBusy(true);try{await call('admin-manage',{action:'ticket-reply',id:selectedTicket.id,admin_reply:reply,status:ticketStatus});setMessage('Resposta e status salvos.');setReply('');setSelectedTicket(null);await loadTickets();await loadDashboard()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function savePost(e){e.preventDefault();setBusy(true);try{await call('admin-manage',{action:'social-save',platform,title:postTitle,caption,media_url:mediaUrl,scheduled_at:postDate?new Date(postDate).toISOString():null,status:postStatus,published_url:publishedUrl});setMessage('Publicação adicionada ao calendário. A postagem automática depende da integração oficial da rede.');setPostTitle('');setCaption('');setMediaUrl('');setPostDate('');setPublishedUrl('');setPostStatus('draft');await loadPosts()}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function deletePost(id){if(!confirm('Excluir este item do calendário?'))return;try{await call('admin-manage',{action:'social-delete',id});await loadPosts();setMessage('Item removido.')}catch(e){setMessage(e.message)}}
  async function createCourse(e){e.preventDefault();setBusy(true);try{const slug=courseTitle.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');const {error}=await supabase.from('courses').insert({title:courseTitle,slug,description:courseDescription,category:courseCategory,icon:'book-open',is_published:false,adult_only:false,sort_order:courses.length+1});if(error)throw error;setMessage('Trilha criada como rascunho. Revise as aulas antes de publicar.');setCourseTitle('');setCourseDescription('');}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function createLesson(e){e.preventDefault();if(!courseId){setMessage('Selecione a trilha.');return}setBusy(true);try{const {error}=await supabase.from('lessons').insert({course_id:courseId,title:lessonTitle,summary:lessonSummary,content_md:lessonContent,estimated_minutes:Number(lessonMinutes),is_published:false,adult_only:false,sort_order:lessons.filter(l=>l.course_id===courseId).length+1});if(error)throw error;setMessage('Aula criada como rascunho.');setLessonTitle('');setLessonSummary('');setLessonContent('');}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  async function updateLesson(e){e.preventDefault();if(!editingLesson)return;setBusy(true);try{const {error}=await supabase.from('lessons').update({title:lessonTitle,summary:lessonSummary,content_md:lessonContent,estimated_minutes:Number(lessonMinutes),updated_at:new Date().toISOString()}).eq('id',editingLesson);if(error)throw error;setMessage('Aula atualizada. Recarregue para refletir as alterações no catálogo.');setEditingLesson(null);setLessonTitle('');setLessonSummary('');setLessonContent('');}catch(e){setMessage(e.message)}finally{setBusy(false)}}
  function editLesson(lesson){setEditingLesson(lesson.id);setCourseId(lesson.course_id);setLessonTitle(lesson.title);setLessonSummary(lesson.summary||'');setLessonContent(lesson.content_md||'');setLessonMinutes(lesson.estimated_minutes||25)}
  const fmt=d=>d?new Date(d).toLocaleString('pt-BR'):'—'
  const filteredUsers=users.filter(u=>!filter||[u.full_name,u.email,u.age_group,u.access_status].join(' ').toLowerCase().includes(filter.toLowerCase()))
  const activityLabel={login:'Entrou na plataforma',onboarding_completed:'Concluiu diagnóstico',course_opened:'Abriu uma trilha',lesson_opened:'Abriu uma aula',lesson_completed:'Concluiu uma aula',tutor_question:'Perguntou ao tutor IA',tool_opened:'Abriu uma ferramenta',support_requested:'Solicitou suporte',project_created:'Criou um projeto'}
  return <section className="workspace admin-workspace">
    <div className="section-heading left"><span className="eyebrow"><ShieldCheck size={14}/> CONTROLE ADMINISTRATIVO</span><h1>Painel de comando AZELF</h1><p>Usuários, aprendizagem, dúvidas, suporte, conteúdo e calendário editorial.</p></div>
    <div className="stats-grid admin-kpis"><Stat label="Usuários cadastrados" value={stats.users} icon={Users}/><Stat label="Acessos ativos" value={stats.active} icon={CheckCircle2}/><Stat label="Aguardando análise" value={stats.pending} icon={ShieldAlert}/><Stat label="Aulas concluídas" value={stats.lessonsDone} icon={GraduationCap}/><Stat label="Perguntas à IA (7 dias)" value={stats.questions} icon={MessageCircle}/><Stat label="Tickets em aberto" value={stats.openTickets} icon={Ticket}/></div>
    <div className="admin-tabs">{[['overview','Visão geral'],['users','Alunos'],['activity','Atividade e dúvidas'],['tickets','Suporte'],['codes','Convites'],['content','Cursos e aulas'],['social','Redes sociais']].map(([k,v])=><button key={k} className={tab===k?'active':''} onClick={()=>switchTab(k)}>{v}</button>)}</div>
    {tab==='overview'&&<div className="admin-overview-grid"><div className="panel admin-chart-panel"><div className="panel-title"><div><span className="eyebrow">ENGAJAMENTO</span><h2>Atividade nos últimos 7 dias</h2></div><button className="outline-button" onClick={loadDashboard}>Atualizar</button></div><ActivityTrend data={trend}/><div className="chart-legend"><span><i className="legend-dot activity-dot"/> Atividade</span><span><i className="legend-dot lesson-dot"/> Aulas concluídas</span><span><i className="legend-dot question-dot"/> Dúvidas à IA</span></div></div><div className="panel admin-shortcuts"><span className="eyebrow">OPERAÇÃO</span><h2>O que precisa de atenção?</h2><button className="admin-shortcut" onClick={()=>switchTab('tickets')}><Ticket/> <span><strong>{stats.openTickets} solicitações</strong><small>Responder alunos que pediram ajuda</small></span><ChevronRight/></button><button className="admin-shortcut" onClick={()=>switchTab('activity')}><MessageCircle/><span><strong>{stats.questions} perguntas recentes</strong><small>Entender dúvidas e pontos de abandono</small></span><ChevronRight/></button><button className="admin-shortcut" onClick={()=>switchTab('social')}><CalendarDays/><span><strong>Calendário editorial</strong><small>Organizar vídeos, posts e links publicados</small></span><ChevronRight/></button><button className="admin-shortcut" onClick={()=>switchTab('content')}><BookOpen/><span><strong>Gestão de conteúdo</strong><small>Criar trilhas e aulas práticas</small></span><ChevronRight/></button></div></div>}
    {tab==='users'&&<div className="panel"><div className="panel-title"><div><span className="eyebrow">BASE DE ALUNOS</span><h2>Quem está usando a AZELF</h2></div><button className="outline-button" onClick={loadUsers}>Atualizar</button></div><div className="search-box"><Search/><input value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Buscar por nome, e-mail ou status…"/></div><div className="admin-table-wrap"><table className="admin-table"><thead><tr><th>Aluno</th><th>Perfil</th><th>Acesso</th><th>Cadastro</th><th>Ação</th></tr></thead><tbody>{filteredUsers.map(u=><tr key={u.id}><td><strong>{u.full_name||'Nome não informado'}</strong><small>{u.email}</small></td><td>{u.role==='admin'?'ADMIN':u.age_group==='minor'?'Menor':'Adulto'}</td><td><span className={'status-pill '+u.access_status}>{u.access_status}</span>{u.guardian_consent_status==='pending'&&<small>Responsável pendente</small>}</td><td>{new Date(u.created_at).toLocaleDateString('pt-BR')}</td><td>{u.role!=='admin'&&(u.access_status==='active'?<button className="danger-button" onClick={()=>setUserStatus(u,'suspended')}>Suspender</button>:<button className="mini-button" onClick={()=>setUserStatus(u,'active')}>{u.age_group==='minor'&&u.guardian_consent_status!=='approved'?'Validar responsável':'Ativar'}</button>)}<button className="text-button" onClick={()=>{setFilter(u.email);switchTab('activity');loadEvents()}}>Ver atividade</button></td></tr>)}</tbody></table></div><p className="admin-footnote">E-mail e status vêm do Supabase Auth e das tabelas protegidas. A lista é limitada aos 200 cadastros mais recentes nesta versão.</p></div>}
    {tab==='activity'&&<div className="panel"><div className="panel-title"><div><span className="eyebrow">RASTREAMENTO DE APRENDIZAGEM</span><h2>O que os alunos estão fazendo</h2></div><button className="outline-button" onClick={loadEvents}>Atualizar</button></div><div className="activity-feed">{events.filter(e=>!filter||[e.email,e.profile?.full_name,e.metadata?.question].join(' ').toLowerCase().includes(filter.toLowerCase())).map(e=><article className="activity-item" key={e.id}><span className="activity-icon">{e.event_type==='tutor_question'?<MessageCircle/>:e.event_type==='lesson_completed'?<CheckCircle2/>:<Activity/>}</span><div><strong>{e.profile?.full_name||e.email||'Aluno'}</strong><small>{activityLabel[e.event_type]||e.event_type} · {fmt(e.created_at)}</small>{e.metadata?.title&&<p>{e.metadata.title}</p>}{e.event_type==='tutor_question'&&e.metadata?.question&&<blockquote className="student-question">“{e.metadata.question}”</blockquote>}</div></article>)}{events.length===0&&<p className="empty">Ainda não há eventos registrados. Conforme os alunos navegam, estudam e perguntam à IA, a atividade aparece aqui.</p>}</div></div>}
    {tab==='tickets'&&<div className="admin-ticket-layout"><div className="panel"><div className="panel-title"><div><span className="eyebrow">CENTRAL DE AJUDA</span><h2>Solicitações dos alunos</h2></div><button className="outline-button" onClick={loadTickets}>Atualizar</button></div><div className="ticket-list">{tickets.map(t=><button className={selectedTicket?.id===t.id?'ticket-row selected':'ticket-row'} key={t.id} onClick={()=>{setSelectedTicket(t);setReply(t.admin_reply||'');setTicketStatus(t.status)}}><strong>{t.subject}</strong><small>{t.profile?.full_name||t.email} · {fmt(t.created_at)}</small><span className={'status-pill '+t.status}>{t.status}</span></button>)}{tickets.length===0&&<p className="empty">Nenhuma solicitação recebida ainda.</p>}</div></div><div className="panel">{selectedTicket?<><span className="eyebrow">ATENDER SOLICITAÇÃO</span><h2>{selectedTicket.subject}</h2><p><strong>{selectedTicket.profile?.full_name||'Aluno'}</strong> · {selectedTicket.email}</p><div className="ticket-message">{selectedTicket.message}</div><label>Status<select value={ticketStatus} onChange={e=>setTicketStatus(e.target.value)}><option value="new">Novo</option><option value="in_progress">Em atendimento</option><option value="waiting_user">Aguardando aluno</option><option value="resolved">Resolvido</option><option value="closed">Fechado</option></select></label><form className="admin-form" onSubmit={answerTicket}><label>Resposta do administrador<textarea rows="6" value={reply} onChange={e=>setReply(e.target.value)} placeholder="Escreva a orientação para o aluno…"/></label><button className="button" disabled={busy}>{busy?'Salvando…':'Salvar resposta'}</button></form><a className="support-wa-link" href={'https://wa.me/'+SUPPORT_WHATSAPP+'?text='+encodeURIComponent('Olá, sou do suporte AZELF. Sobre: '+selectedTicket.subject)} target="_blank" rel="noreferrer">Abrir WhatsApp <ExternalLink size={14}/></a></>:<div className="empty ticket-empty"><Headphones size={30}/><strong>Selecione uma solicitação</strong><p>Leia a mensagem do aluno e responda por aqui. A resposta fica registrada no histórico do ticket.</p></div>}</div></div>}
    {tab==='codes'&&<div className="admin-code-layout"><div className="panel"><h2>Gerar convite de acesso</h2><p>Cada aluno recebe um código único vinculado ao e-mail dele. Sem código válido, não consegue concluir o cadastro.</p><form onSubmit={generate} className="admin-form"><label>E-mail do comprador/aluno<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required placeholder="cliente@email.com"/></label><label>Identificação (opcional)<input value={label} onChange={e=>setLabel(e.target.value)} placeholder="Nome, pedido ou turma"/></label><label>Validade<select value={days} onChange={e=>setDays(e.target.value)}><option value="7">7 dias</option><option value="30">30 dias</option><option value="60">60 dias</option><option value="90">90 dias</option></select></label><button className="button" disabled={busy}>{busy?'Gerando…':'Gerar convite'}</button></form>{newCode&&<div className="generated-code"><strong>Código gerado — copie e envie ao aluno</strong><code>{newCode}</code><button className="outline-button" onClick={()=>navigator.clipboard?.writeText(newCode)}>Copiar código</button><a className="support-wa-link" href={'https://wa.me/?text='+encodeURIComponent('Seu convite AZELF: '+newCode+' · Cadastre-se em https://azelfone.pages.dev')} target="_blank" rel="noreferrer">Compartilhar convite <Send size={14}/></a></div>}</div><div className="panel"><div className="panel-title"><h2>Histórico de convites</h2><button className="outline-button" onClick={loadCodes}>Atualizar</button></div><div className="admin-list">{codes.map(code=><div className="admin-user" key={code.id}><div><strong>{code.customer_label||'Convite AZELF'}</strong><small>Criado: {fmt(code.created_at)} · Expira: {fmt(code.expires_at)}</small><small>{code.revoked_at?'Revogado':code.redeemed_by?'Utilizado':code.reserved_email?'Em reserva':'Disponível'}{code.reserved_email?' · '+code.reserved_email:''}</small></div>{!code.redeemed_by&&!code.revoked_at&&<button className="danger-button" onClick={()=>revoke(code.id)}>Revogar</button>}</div>)}</div></div></div>}
    {tab==='content'&&<div className="admin-content-grid"><div className="panel"><span className="eyebrow">NOVA TRILHA</span><h2>Criar módulo de aprendizagem</h2><form className="admin-form" onSubmit={createCourse}><label>Nome do módulo<input required value={courseTitle} onChange={e=>setCourseTitle(e.target.value)} placeholder="Ex.: Automação com IA"/></label><label>Categoria<input required value={courseCategory} onChange={e=>setCourseCategory(e.target.value)} placeholder="Tecnologia, vendas…"/></label><label>Descrição<textarea rows="3" value={courseDescription} onChange={e=>setCourseDescription(e.target.value)} placeholder="Qual transformação o aluno vai conseguir realizar?"/></label><button className="button" disabled={busy}>Criar trilha como rascunho</button></form></div><div className="panel"><span className="eyebrow">NOVA AULA</span><h2>Criar ou editar uma aula</h2><form className="admin-form" onSubmit={editingLesson?updateLesson:createLesson}><label>Trilha<select value={courseId} onChange={e=>setCourseId(e.target.value)}>{courses.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label><label>Título da aula<input required value={lessonTitle} onChange={e=>setLessonTitle(e.target.value)} placeholder="Resultado prático desta aula"/></label><label>Resumo<input value={lessonSummary} onChange={e=>setLessonSummary(e.target.value)} placeholder="O que o aluno vai fazer?"/></label><label>Conteúdo com demonstração, checklist e exercício<textarea rows="7" required value={lessonContent} onChange={e=>setLessonContent(e.target.value)} placeholder={'## Objetivo\n\n## Demonstração\n\n## Prática guiada\n\n## Desafio\n\n## Critério de conclusão'}/></label><label>Duração estimada (minutos)<input type="number" min="5" max="240" value={lessonMinutes} onChange={e=>setLessonMinutes(e.target.value)}/></label><div className="row-actions"><button className="button" disabled={busy}>{editingLesson?'Salvar alterações':'Criar aula como rascunho'}</button>{editingLesson&&<button type="button" className="outline-button" onClick={()=>{setEditingLesson(null);setLessonTitle('');setLessonSummary('');setLessonContent('')}}>Cancelar edição</button>}</div></form></div><div className="panel content-list-panel"><div className="panel-title"><h2>Trilhas e aulas existentes</h2><span className="muted">{courses.length} trilhas · {lessons.length} aulas</span></div>{courses.map(course=><details className="content-course" key={course.id}><summary>{course.title} <span>{lessons.filter(l=>l.course_id===course.id).length} aulas</span></summary>{lessons.filter(l=>l.course_id===course.id).map(l=><div className="content-lesson-row" key={l.id}><span><strong>{l.title}</strong><small>{l.summary}</small></span><button className="mini-button" onClick={()=>editLesson(l)}>Editar aula</button></div>)}</details>)}</div></div>}
    {tab==='social'&&<div className="admin-social-grid"><div className="panel"><span className="eyebrow">CALENDÁRIO EDITORIAL</span><h2>Planejar publicação</h2><form className="admin-form" onSubmit={savePost}><label>Rede social<select value={platform} onChange={e=>setPlatform(e.target.value)}><option value="instagram">Instagram</option><option value="tiktok">TikTok</option><option value="youtube">YouTube</option><option value="facebook">Facebook</option><option value="linkedin">LinkedIn</option><option value="x">X</option><option value="other">Outra</option></select></label><label>Título/tema<input required value={postTitle} onChange={e=>setPostTitle(e.target.value)} placeholder="Ex.: como funciona uma blockchain"/></label><label>Legenda e roteiro<textarea rows="6" value={caption} onChange={e=>setCaption(e.target.value)} placeholder="Gancho, conteúdo, CTA e aviso de publicidade, se aplicável…"/></label><label>Link do vídeo ou arquivo de mídia<input value={mediaUrl} onChange={e=>setMediaUrl(e.target.value)} placeholder="Link do vídeo que você vai enviar depois"/></label><label>Data planejada<input type="datetime-local" value={postDate} onChange={e=>setPostDate(e.target.value)}/></label><label>Status<select value={postStatus} onChange={e=>setPostStatus(e.target.value)}><option value="draft">Rascunho</option><option value="ready">Pronto para revisão</option><option value="scheduled">Agendado (manual)</option><option value="published">Já publicado</option></select></label>{postStatus==='published'&&<label>Link publicado<input value={publishedUrl} onChange={e=>setPublishedUrl(e.target.value)} placeholder="URL do post publicado"/></label>}<button className="button" disabled={busy}>Salvar no calendário</button></form><p className="admin-footnote">Esta agenda organiza os conteúdos. Ela não publica automaticamente: para isso será necessário conectar as contas oficiais e autorizações/API de cada rede.</p></div><div className="panel"><div className="panel-title"><h2>Fila de publicações</h2><button className="outline-button" onClick={loadPosts}>Atualizar</button></div><div className="admin-list">{posts.map(p=><div className="social-post-row" key={p.id}><div><strong>{p.title}</strong><small>{p.platform.toUpperCase()} · {p.status} · {fmt(p.scheduled_at)}</small>{p.caption&&<p>{p.caption.slice(0,180)}</p>}{p.media_url&&<a href={p.media_url} target="_blank" rel="noreferrer">Abrir mídia <ExternalLink size={12}/></a>}{p.published_url&&<a href={p.published_url} target="_blank" rel="noreferrer">Ver publicação <ExternalLink size={12}/></a>}</div><button className="danger-button" onClick={()=>deletePost(p.id)}><Trash2 size={14}/></button></div>)}{posts.length===0&&<p className="empty">Nenhum conteúdo planejado. Adicione seu primeiro vídeo ou post.</p>}</div></div></div>}
    {message&&<p className="notice">{message}</p>}
    <p className="admin-footnote">O painel usa autorização administrativa verificada no servidor. Alterações de status, convites, tickets e calendário são registradas no Supabase.</p>
  </section>
}
function ActivityTrend({data=[]}){const max=Math.max(1,...data.map(d=>Math.max(d.activity||0,d.lessons||0,d.questions||0)));const x=i=>28+i*(544/Math.max(1,data.length-1));const y=v=>150-(v/max*118);const line=k=>data.map((d,i)=>x(i)+','+y(d[k]||0)).join(' ');return <div className="activity-chart"><svg viewBox="0 0 590 190" role="img" aria-label="Gráfico de atividade semanal"><line x1="28" y1="150" x2="572" y2="150" className="chart-axis"/><line x1="28" y1="91" x2="572" y2="91" className="chart-gridline"/><line x1="28" y1="32" x2="572" y2="32" className="chart-gridline"/><polyline points={line('activity')} className="chart-line activity-line"/><polyline points={line('lessons')} className="chart-line lessons-line"/><polyline points={line('questions')} className="chart-line questions-line"/>{data.map((d,i)=><text key={d.key||i} x={x(i)} y="177" textAnchor="middle" className="chart-label">{d.label}</text>)}</svg></div>}

function LearningLab({openCrypto}){
  return <section className="workspace lab-page">
    <div className="section-heading left"><span className="eyebrow">APRENDER FAZENDO</span><h1>Laboratórios AZELF</h1><p>Pratique em ambientes simulados: entenda o mecanismo, teste hipóteses e veja o resultado antes de executar algo no mundo real.</p></div>
    <div className="lab-grid">
      <article className="lab-card crypto-lab-card"><div className="lab-card-visual"><div className="lab-token-orbit"><Blocks size={48}/><span className="token-dot dot-a"/><span className="token-dot dot-b"/><span className="token-dot dot-c"/></div><span className="lab-label">BLOCKCHAIN · SIMULAÇÃO</span></div><div className="lab-card-body"><span className="eyebrow">LAB 01</span><h2>Crie um token e monte uma blockchain</h2><p>Configure nome, símbolo e oferta fictícia; envie uma transação simulada; agrupe-a em um bloco e acompanhe o encadeamento por hash.</p><ul><li>Token e oferta</li><li>Carteira e transações fictícias</li><li>Blocos, hash e consenso explicado</li></ul><button className="button" onClick={openCrypto}>Entrar no laboratório <ArrowRight size={16}/></button></div></article>
      <article className="lab-card market-lab-card"><div className="lab-card-visual"><div className="market-lines"><svg viewBox="0 0 360 150"><polyline points="0,118 35,95 70,104 105,68 140,78 175,42 210,60 245,30 280,48 320,12 360,25" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round"/><polyline points="0,118 35,95 70,104 105,68 140,78 175,42 210,60 245,30 280,48 320,12 360,25 360,150 0,150" fill="currentColor" opacity=".08"/></svg></div><span className="lab-label">MERCADO · PAPER TRADING</span></div><div className="lab-card-body"><span className="eyebrow">LAB 02</span><h2>Gráficos, risco e simulação de operações</h2><p>Leia séries hipotéticas, compare períodos, calcule posição e observe como preço, taxa e risco alteram um saldo simulado.</p><ul><li>Gráfico com períodos</li><li>Compra e venda fictícias</li><li>Resultado, custo e drawdown</li></ul><button className="outline-button" onClick={openCrypto}>Abrir simuladores <ArrowRight size={16}/></button></div></article>
      <article className="lab-card business-lab-card"><div className="lab-card-visual"><div className="profit-stack"><span>RECEITA</span><strong>− CUSTOS</strong><em>= MARGEM</em></div><span className="lab-label">NEGÓCIOS · UNIT ECONOMICS</span></div><div className="lab-card-body"><span className="eyebrow">LAB 03</span><h2>Monte uma oferta e descubra a margem</h2><p>Simule preço, custo variável, investimento em marketing e quantidade vendida. Veja faturamento, lucro operacional e ponto de equilíbrio.</p><ul><li>Preço e custo unitário</li><li>Margem de contribuição</li><li>ROI e ponto de equilíbrio</li></ul><button className="outline-button" onClick={openCrypto}>Abrir simuladores <ArrowRight size={16}/></button></div></article>
    </div>
    <p className="lab-disclaimer">Todos os valores dos laboratórios são hipotéticos. Nenhuma ordem real é enviada, nenhum token é publicado em uma rede e nenhum valor financeiro é movimentado.</p>
  </section>
}

function CryptoLab({back}){
  const [active,setActive]=useState('chain'),[tokenName,setTokenName]=useState('Azelf Academy Token'),[symbol,setSymbol]=useState('AZL'),[supply,setSupply]=useState('1000000'),[token,setToken]=useState(null)
  const [recipient,setRecipient]=useState('carteira-demo-02'),[amount,setAmount]=useState('25'),[pending,setPending]=useState([]),[blocks,setBlocks]=useState([{height:0,hash:'0000GENESIS-AZELF',previous:'—',transactions:['Bloco gênesis do laboratório'],time:new Date().toLocaleTimeString('pt-BR')}])
  const [balance,setBalance]=useState(10000),[holding,setHolding]=useState(0),[tradeAmount,setTradeAmount]=useState('500'),[lastTrade,setLastTrade]=useState(''),[period,setPeriod]=useState('30D')
  const [price,setPrice]=useState(105.5),[businessPrice,setBusinessPrice]=useState(89),[unitCost,setUnitCost]=useState(28),[marketing,setMarketing]=useState(450),[sales,setSales]=useState(32)
  const series={7:[100,102,99,104,106,103,108,111,109,114,112,116],30:[100,97,101,103,99,104,106,102,109,107,112,115,111,118,116,121],90:[100,104,98,101,96,105,109,103,111,108,115,112,121,119,124,118,128,133]}
  const values=series[period]
  const max=Math.max(...values),min=Math.min(...values),points=values.map((v,i)=>(24+i*452/(values.length-1))+','+(132-(v-min)/(max-min||1)*105)).join(' ')
  const revenue=businessPrice*sales,cogs=unitCost*sales,contribution=revenue-cogs,profit=contribution-marketing,breakEven=businessPrice>unitCost?Math.ceil(marketing/(businessPrice-unitCost)):null
  function createToken(e){e.preventDefault();if(!tokenName.trim()||!symbol.trim()||Number(supply)<=0)return;const short='0x'+Array.from({length:8},()=>Math.floor(Math.random()*16).toString(16)).join('');setToken({name:tokenName.trim(),symbol:symbol.trim().toUpperCase(),supply:Number(supply),address:short,createdAt:new Date().toLocaleTimeString('pt-BR')})}
  function addTransaction(e){e.preventDefault();if(Number(amount)<=0||!recipient.trim())return;setPending(p=>[...p,{id:'TX-'+Date.now().toString(36).toUpperCase(),from:'carteira-demo-01',to:recipient.trim(),amount:Number(amount),status:'pendente'}]);setRecipient('');setAmount('25')}
  function mineBlock(){if(!pending.length)return;const previous=blocks[blocks.length-1].hash;const height=blocks.length;const hash='0x'+Array.from({length:24},()=>Math.floor(Math.random()*16).toString(16)).join('');setBlocks(b=>[...b,{height,hash,previous,transactions:pending.map(t=>t.from+' → '+t.to+': '+t.amount+' '+(token?.symbol||'DEMO')),time:new Date().toLocaleTimeString('pt-BR')}]);setPending([])}
  function trade(side){const amountValue=Number(tradeAmount);if(!amountValue||amountValue<=0)return;const units=amountValue/price;const fee=amountValue*.001; if(side==='buy'){if(amountValue+fee>balance){setLastTrade('Saldo simulado insuficiente.');return}setBalance(b=>b-amountValue-fee);setHolding(h=>h+units);setLastTrade('Compra simulada: '+units.toFixed(4)+' unidades. Custo fictício '+fee.toFixed(2)+'.')}else{if(units>holding){setLastTrade('Você não possui unidades suficientes na carteira de simulação.');return}setBalance(b=>b+amountValue-fee);setHolding(h=>h-units);setLastTrade('Venda simulada: '+units.toFixed(4)+' unidades. Taxa fictícia '+fee.toFixed(2)+'.')}}
  return <section className="workspace crypto-lab">
    <button className="back-button" onClick={back}>← Voltar aos laboratórios</button>
    <div className="section-heading left"><span className="eyebrow">LABORATÓRIO 01 · AMBIENTE FICTÍCIO</span><h1>Veja a tecnologia funcionando.</h1><p>Crie um ativo de demonstração, envie transações de teste, agrupe-as em blocos e experimente gráficos e cálculos de mercado sem conexão com corretoras ou carteiras reais.</p></div>
    <div className="lab-tabs"><button className={active==='chain'?'active':''} onClick={()=>setActive('chain')}><Blocks size={15}/> Criar token e blockchain</button><button className={active==='market'?'active':''} onClick={()=>setActive('market')}><BarChart3 size={15}/> Gráfico e trading simulado</button><button className={active==='business'?'active':''} onClick={()=>setActive('business')}><Wallet size={15}/> Simulador de negócio</button></div>
    {active==='chain'&&<div className="chain-lab-grid">
      <div className="panel"><span className="eyebrow">ETAPA 1 · TOKEN DE DEMONSTRAÇÃO</span><h2>Configure seu ativo</h2><form className="admin-form" onSubmit={createToken}><label>Nome do token<input value={tokenName} onChange={e=>setTokenName(e.target.value)} required placeholder="Ex.: Azelf Academy Token"/></label><label>Símbolo<input value={symbol} onChange={e=>setSymbol(e.target.value.toUpperCase().slice(0,8))} required maxLength="8" placeholder="AZL"/></label><label>Oferta inicial<input type="number" min="1" step="1" value={supply} onChange={e=>setSupply(e.target.value)}/></label><button className="button">Criar token fictício <Sparkles size={15}/></button></form>{token&&<div className="token-created"><span className="token-created-mark">{token.symbol.slice(0,1)}</span><div><strong>{token.name} ({token.symbol})</strong><small>Oferta: {token.supply.toLocaleString('pt-BR')} · ID simulado {token.address}</small><small>Criado às {token.createdAt} · sem contrato em rede pública</small></div></div>}<div className="concept-note"><strong>O que acontece em uma rede real?</strong><p>O criador define parâmetros e publica um contrato inteligente numa rede compatível. A transação é assinada, paga taxas, validada pela rede e fica registrada. Este laboratório apenas demonstra o fluxo.</p></div></div>
      <div className="panel"><span className="eyebrow">ETAPA 2 · MEMPOOL DE TESTE</span><h2>Monte uma transação</h2><form className="admin-form" onSubmit={addTransaction}><label>Carteira de destino<input value={recipient} onChange={e=>setRecipient(e.target.value)} placeholder="carteira-demo-02"/></label><label>Quantidade<input type="number" min="0.01" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)}/></label><button className="outline-button">Adicionar à fila de transações <Plus size={14}/></button></form><div className="pending-head"><strong>Transações aguardando bloco</strong><span>{pending.length}</span></div>{pending.map(tx=><div className="pending-tx" key={tx.id}><span><strong>{tx.amount} {token?.symbol||'DEMO'}</strong><small>{tx.from} → {tx.to}</small></span><span className="status-pill pending">Pendente</span></div>)}{pending.length===0&&<p className="empty">A fila está vazia. Adicione uma transação simulada.</p>}<button className="button button-full" onClick={mineBlock} disabled={!pending.length}>Minerar bloco de demonstração <Blocks size={15}/></button></div>
      <div className="panel blockchain-panel"><div className="panel-title"><div><span className="eyebrow">ETAPA 3 · CADEIA DE BLOCOS</span><h2>Registro encadeado</h2></div><span className="status-pill active">{blocks.length} blocos</span></div><div className="block-chain">{[...blocks].reverse().map(block=><article className="block-card" key={block.height}><div className="block-card-head"><strong>Bloco #{block.height}</strong><small>{block.time}</small></div><code>Hash: {block.hash}</code><small>Hash anterior: {block.previous}</small><div className="block-transactions">{block.transactions.map((t,i)=><span key={i}>{t}</span>)}</div></article>)}</div></div>
      <div className="panel"><span className="eyebrow">O QUE VOCÊ ACABOU DE VER</span><h2>Como os conceitos se conectam</h2><ol className="learning-steps"><li><strong>Token:</strong> regras e unidades digitais definidas por protocolo ou contrato.</li><li><strong>Transação:</strong> instrução assinada para mudar o estado do livro-razão.</li><li><strong>Mempool:</strong> transações aguardando seleção/validação.</li><li><strong>Bloco:</strong> conjunto ordenado de transações.</li><li><strong>Hash:</strong> resumo criptográfico que ajuda a detectar alteração.</li><li><strong>Consenso:</strong> regra que permite à rede concordar sobre a ordem e validade dos blocos.</li></ol><div className="concept-note"><strong>Limite desta experiência</strong><p>O botão “minerar” cria um registro visual local. Não existe mineração real, carteira, emissão de moeda negociável ou gravação em blockchain pública.</p></div></div>
    </div>}
    {active==='market'&&<div className="market-lab-grid"><div className="panel market-chart-panel"><div className="panel-title"><div><span className="eyebrow">SÉRIE HIPOTÉTICA</span><h2>Preço de demonstração</h2></div><span className="market-price">R$ {price.toFixed(2).replace('.',',')}</span></div><div className="period-tabs">{[['7','7D'],['30','30D'],['90','90D']].map(([k,v])=><button key={k} className={period===v?'active':''} onClick={()=>setPeriod(v)}>{v}</button>)}</div><svg className="market-chart" viewBox="0 0 500 160" preserveAspectRatio="none"><line x1="24" y1="132" x2="476" y2="132" className="chart-axis"/><line x1="24" y1="78" x2="476" y2="78" className="chart-gridline"/><line x1="24" y1="26" x2="476" y2="26" className="chart-gridline"/><polyline points={points} className="market-series"/><circle cx="476" cy={132-(values[values.length-1]-min)/(max-min||1)*105} r="4" className="market-point"/></svg><div className="market-summary"><span>Variação do cenário: <strong>{((values[values.length-1]/values[0]-1)*100).toFixed(2)}%</strong></span><span>Intervalo: {min.toFixed(1)} – {max.toFixed(1)}</span></div><div className="concept-note"><strong>Dados de treinamento</strong><p>Esta série é sintética e foi criada apenas para praticar leitura de gráfico. Não representa cotação atual nem histórico de ativo negociado.</p></div></div><div className="panel"><span className="eyebrow">PAPER TRADING</span><h2>Teste uma operação no papel</h2><div className="paper-wallet"><div><small>Saldo de simulação</small><strong>R$ {balance.toFixed(2)}</strong></div><div><small>Posição</small><strong>{holding.toFixed(4)} un.</strong></div></div><label>Preço hipotético<input value={'R$ '+price.toFixed(2)} readOnly/></label><label>Valor da ordem (R$)<input type="number" min="1" step="10" value={tradeAmount} onChange={e=>setTradeAmount(e.target.value)}/></label><div className="row-actions"><button className="button" onClick={()=>trade('buy')}>Comprar simulado</button><button className="outline-button" onClick={()=>trade('sell')}>Vender simulado</button></div>{lastTrade&&<p className="notice">{lastTrade}</p>}<div className="concept-note"><strong>O que observar</strong><p>Uma taxa fictícia de 0,10% já foi incluída. Experimente aumentar o valor da ordem e observe o saldo e a posição. Em mercados reais, também existem spread, slippage, impostos, liquidez e risco de perda.</p></div></div></div>}
    {active==='business'&&<div className="business-lab-grid"><div className="panel"><span className="eyebrow">UNIT ECONOMICS</span><h2>Configure sua oferta</h2><label>Preço por venda (R$)<input type="number" min="0" step="1" value={businessPrice} onChange={e=>setBusinessPrice(Number(e.target.value))}/></label><label>Custo variável por venda (R$)<input type="number" min="0" step="1" value={unitCost} onChange={e=>setUnitCost(Number(e.target.value))}/></label><label>Marketing e custos fixos do período (R$)<input type="number" min="0" step="10" value={marketing} onChange={e=>setMarketing(Number(e.target.value))}/></label><label>Quantidade de vendas<input type="range" min="0" max="200" value={sales} onChange={e=>setSales(Number(e.target.value))}/><strong>{sales} vendas</strong></label></div><div className="panel business-result"><span className="eyebrow">RESULTADO DO CENÁRIO</span><h2>Seu negócio em números</h2><div className="result-row"><span>Faturamento</span><strong>R$ {revenue.toFixed(2)}</strong></div><div className="result-row"><span>Custos variáveis</span><strong>− R$ {cogs.toFixed(2)}</strong></div><div className="result-row"><span>Margem de contribuição</span><strong>R$ {contribution.toFixed(2)}</strong></div><div className="result-row"><span>Custos fixos/marketing</span><strong>− R$ {marketing.toFixed(2)}</strong></div><div className="result-total"><span>Resultado estimado</span><strong className={profit>=0?'positive':'negative'}>R$ {profit.toFixed(2)}</strong></div><div className="break-even">Ponto de equilíbrio: <strong>{breakEven===null?'Não há margem por unidade':breakEven+' vendas'}</strong></div><div className="concept-note"><strong>Interpretação</strong><p>Margem positiva por unidade não garante lucro do negócio. O volume precisa cobrir custos fixos, marketing, impostos, taxas, devoluções e trabalho do empreendedor.</p></div></div></div>}
    <p className="lab-disclaimer">AZELF é um ambiente educacional. Os dados são simulados. Não há conexão com exchanges, corretoras, carteiras ou contratos em redes públicas. Não constitui recomendação financeira.</p>
  </section>
}

function Support({session,profile,onTicketCreated}){
  const [subject,setSubject]=useState(''),[category,setCategory]=useState('duvida'),[message,setMessage]=useState(''),[tickets,setTickets]=useState([]),[busy,setBusy]=useState(false),[notice,setNotice]=useState('')
  async function load(){const {data,error}=await supabase.from('support_tickets').select('id,subject,category,message,status,admin_reply,created_at,updated_at').eq('user_id',session.user.id).order('created_at',{ascending:false}).limit(20);if(error)setNotice(error.message);else setTickets(data||[])}
  useEffect(()=>{load()},[session.user.id])
  async function submit(e){e.preventDefault();setBusy(true);setNotice('');const {error}=await supabase.from('support_tickets').insert({user_id:session.user.id,subject,category,message});setBusy(false);if(error){setNotice('Não foi possível enviar: '+error.message);return}setNotice('Solicitação enviada. A equipe AZELF poderá responder pelo histórico desta área.');setSubject('');setMessage('');onTicketCreated?.();await load()}
  return <section className="workspace support-page"><div className="section-heading left"><span className="eyebrow"><Headphones size={14}/> SUPORTE AZELF</span><h1>Você não precisa resolver tudo sozinho.</h1><p>Envie sua dúvida, descreva onde travou e acompanhe a resposta da equipe.</p></div><div className="support-grid"><div className="panel"><h2>Fale com a equipe</h2><form className="admin-form" onSubmit={submit}><label>Assunto<input required minLength="3" maxLength="160" value={subject} onChange={e=>setSubject(e.target.value)} placeholder="Ex.: não consigo concluir uma aula"/></label><label>Tipo de solicitação<select value={category} onChange={e=>setCategory(e.target.value)}><option value="duvida">Dúvida de aprendizagem</option><option value="acesso">Acesso ou cadastro</option><option value="curso">Curso ou aula</option><option value="pagamento">Pagamento ou convite</option><option value="sugestao">Sugestão de melhoria</option><option value="outro">Outro assunto</option></select></label><label>Conte o que aconteceu<textarea required minLength="10" maxLength="5000" rows="6" value={message} onChange={e=>setMessage(e.target.value)} placeholder="Descreva o objetivo, o que tentou fazer e a mensagem que apareceu. Não envie senhas, códigos ou frases de recuperação."/></label><button className="button" disabled={busy}>{busy?'Enviando…':'Enviar solicitação'} <Send size={15}/></button></form>{notice&&<p className="notice">{notice}</p>}<a className="support-wa-link" href={'https://wa.me/'+SUPPORT_WHATSAPP+'?text='+encodeURIComponent('Olá, preciso de ajuda com a AZELF. Meu e-mail de cadastro é '+(session.user.email||''))} target="_blank" rel="noreferrer">Abrir conversa no WhatsApp <ExternalLink size={14}/></a><p className="admin-footnote">O botão abre uma conversa no seu WhatsApp. O envio só acontece quando você confirmar dentro do aplicativo. O ticket também fica salvo no painel ADMIN.</p></div><div className="panel"><span className="eyebrow">MEUS PEDIDOS DE AJUDA</span><h2>Histórico de solicitações</h2><div className="support-history">{tickets.map(t=><article className="support-ticket-card" key={t.id}><div className="ticket-title-row"><strong>{t.subject}</strong><span className={'status-pill '+t.status}>{t.status}</span></div><small>{new Date(t.created_at).toLocaleString('pt-BR')} · {t.category}</small><p>{t.message}</p>{t.admin_reply&&<div className="admin-response"><strong>Resposta AZELF</strong><p>{t.admin_reply}</p></div>}</article>)}{tickets.length===0&&<p className="empty">Você ainda não abriu solicitações. Quando precisar, envie uma mensagem pelo formulário.</p>}</div></div></div></section>
}

export default App;